"""One ticker's worst fall from a peak; `depth` is at most 0, from `peak_date` to `trough_date`."""

ticker: str
depth: float
peak_date: str
trough_date: str

def __post_init__(self) -> None:
    if not self.depth <= 0:
        raise ValueError("depth must be at most 0")
    if date.fromisoformat(self.peak_date) > date.fromisoformat(self.trough_date):
        raise ValueError("peak_date must not be after trough_date")

